import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int k = fs.nextInt();
        int c = fs.nextInt();

        int[] a = new int[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            total += a[i];
        }

        if (c == 1) {
            Arrays.sort(a);
            long covered = 0;
            for (int i = 0; i < k; i++) covered += a[i];
            System.out.println(total - covered);
            return;
        }

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + a[i];
        }

        int ringSize = c + 1;
        long[][] dp = new long[ringSize][k + 1];
        dp[0][0] = 0;

        final long INF = Long.MAX_VALUE / 4;

        for (int i = 1; i <= n; i++) {
            int currentIndex = i % ringSize;
            int previousIndex = (i - 1) % ringSize;
            long[] current = dp[currentIndex];
            long[] previous = dp[previousIndex];

            int maxK = Math.min(k, i / c);
            long[] source = null;
            long intervalSum = 0;

            if (i >= c) {
                source = dp[(i - c) % ringSize];
                intervalSum = prefix[i] - prefix[i - c];
            }

            for (int count = 0; count <= maxK; count++) {
                long best = previous[count];
                if (count > 0 && source != null && source[count - 1] != INF) {
                    best = Math.min(best, source[count - 1] + intervalSum);
                }
                current[count] = best;
            }
        }

        System.out.println(total - dp[n % ringSize][k]);
    }
}
